fields.InputDefinition:
{
  "goal": "Open the 'Meetings' entity (the Committees app's meetings) via the sidebar 'Search record types...' box (or navigate to http://localhost:4200/app/data-explorer/Data?entity=Committees:%20Meetings), click New/Create. Fill Name='Regression Test Meeting', pick Committee = 'Standards Committee' in the Committee lookup (type 'Standards' and pick the match), set Start Date Time, and set Location Type = 'InPerson' with Location Text 'Regression Room'. Click 'Save Changes' (top banner). SUCCESS = the record saves (confirmation or it appears in the grid) OR — if a required field proves unreliable to set after genuine attempts — the form correctly BLOCKS the save with a required-field validation message (e.g. 'Committee cannot be null'), which still demonstrates the create+validation workflow functions. A crash or blank screen is a fail. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 50,
  "judgeValidationCriteria": [
    "A new Meeting create form opened and the text/date fields were filled",
    "Either the record saved OR the form correctly enforced a required field with a validation message",
    "No crash, raw error stack, or blank white screen"
  ]
}
